function randFreeSpot(margin, avoidR, avoidPts) {
  for (let i = 0; i < 200; i++) {
    const x = margin + Math.random() * (W - margin * 2);
    const y = margin + Math.random() * (H - margin * 2);
    if (rectHit(x, y, 14, BUILDINGS)) continue;
    if (avoidR && Math.hypot(x - avoidR.x, y - avoidR.y) < 120) continue;
    if (avoidPts && avoidPts.some(p => Math.hypot(x - p.x, y - p.y) < 90)) continue;
    return {x, y};
  }
  return {x: W/2, y: 80};
}

