function startGame() {
  player = {x: W/2, y: H - 50, r: 12, vx: 0, vy: 0, angle: -Math.PI/2};
  score = 0; lives = MAX_LIVES; timeLeft = TIME_LIMIT; collected = 0;
  elapsed = 0; shake = 0; flashT = 0; boostT = 0; invulnT = 0;
  paused = false;
  particles = []; trail = [];
  // 5 patrolling blockers on lanes that steer clear of solid buildings
  blockers = [
    mkBlocker('h', 90, 250, 200, 130),
    mkBlocker('v', 300, 90, 160, 240),
    mkBlocker('h', 540, 262, 220, 110),
    mkBlocker('v', 695, 300, 150, 280),
    mkBlocker('h', 170, 312, 260, 280),
  ];
  orbs = [];
  const homes = blockers.map(b => ({x: b.hx, y: b.hy}));
  for (let i = 0; i < TOTAL_ORBS; i++) {
    const s = randFreeSpot(40, player, homes);
    orbs.push({x: s.x, y: s.y, r: 10, phase: Math.random() * Math.PI * 2, taken: false});
  }
  state = 'playing';
  overlay.classList.add('hidden');
  updateHUD();
  beep(520, .08, 'square', .12);
}

function togglePause(force) {
  paused = force === true ? true : !paused;
  if (paused) {
    ovTitle.textContent = 'PAUSED ❚❚';
    ovText.innerHTML = `Courier holding position. Score <b>${score}</b> · Orbs <b>${collected}/${TOTAL_ORBS}</b> · <b>${Math.ceil(timeLeft)}s</b> left.<br>` +
      `<span class="keys"><kbd>P</kbd> / <kbd>Esc</kbd> to resume</span>`;
    startBtn.textContent = '▶ RESUME';
    overlay.classList.remove('hidden');
  } else {
    overlay.classList.add('hidden');
  }
}

